parameters.jsCode:
/**
 * PULSO RAG v2
 * Primer nodo: Code in JavaScript
 * Modo: Run Once for Each Item
 *
 * Responsabilidades:
 * - Preservar la salida del ML Service y SHAP.
 * - Calcular proximidad al umbral solo para uso interno.
 * - Validar coherencia básica de los datos.
 * - Distinguir explicación, cambio y mantenimiento.
 * - Preparar contexto educativo y consultas documentales.
 *
 * NO hace diagnósticos ni decide tratamientos.
 */

const body = $json.body ?? $json;
const prediction = body.prediction;
const user = body.user_data;
const shap = body.shap;

if (!prediction || !user || !shap || !Array.isArray(shap.top_factors)) {
  throw new Error("Se requieren prediction, user_data y shap.top_factors.");
}

function numeric(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function textValue(value) {
  return value === null || value === undefined || value === ""
    ? "no disponible"
    : String(value);
}

const probability = numeric(prediction.probability);
const threshold = numeric(prediction.threshold);

if (probability === null || probability < 0 || probability > 1) {
  throw new Error("Probabilidad inválida.");
}

if (threshold === null || threshold <= 0 || threshold > 1) {
  throw new Error("Umbral inválido.");
}

// ==========================================
// 1. UMBRAL: INFORMACIÓN EXCLUSIVAMENTE INTERNA
// ==========================================

const signedDistance = probability - threshold;
const absoluteDistance = Math.abs(signedDistance);
const relativeGap = absoluteDistance / threshold;
const epsilon = 1e-10;

const thresholdPosition =
  absoluteDistance < epsilon
    ? "at_threshold"
    : signedDistance < 0
      ? "below_threshold"
      : "above_threshold";

const proximityCategory =
  relativeGap <= 0.1 ? "very_close" : relativeGap <= 0.3 ? "close" : "far";

const proximityNames = {
  very_close: "muy próximo",
  close: "próximo",
  far: "alejado",
};

const positionNames = {
  below_threshold: "por debajo",
  above_threshold: "por encima",
  at_threshold: "en el umbral",
};

const thresholdProximity =
  thresholdPosition === "at_threshold"
    ? "exactamente en el umbral"
    : `${proximityNames[proximityCategory]} ${
        positionNames[thresholdPosition]
      }`;

const thresholdMetadata = {
  probability,
  threshold,
  position: thresholdPosition,
  proximity_category: proximityCategory,
  proximity_label: thresholdProximity,
  signed_distance: Number(signedDistance.toFixed(8)),
  absolute_distance: Number(absoluteDistance.toFixed(8)),
  distance_to_threshold_pp: Number((signedDistance * 100).toFixed(4)),
  relative_distance_percent: Number((relativeGap * 100).toFixed(4)),
};

// ==========================================
// 2. DICCIONARIOS DE INTERPRETACIÓN
// ==========================================

const genderMap = {
  1: "mujer",
  2: "hombre",
};

const smokeMap = {
  0: "no fumador",
  1: "fumador",
};

const alcoholMap = {
  0: "no declara consumo de alcohol",
  1: "declara consumo de alcohol",
};

const activityMap = {
  0: "no declara actividad física",
  1: "declara actividad física",
};

const featureToGroup = {
  ap_hi: "blood_pressure",
  ap_lo: "blood_pressure",
  smoke: "smoking",
  active: "physical_activity",
  weight: "weight_bmi",
  bmi: "weight_bmi",
  alco: "alcohol",
};

const groupTerms = {
  blood_pressure:
    "presión arterial, relación con salud cardiovascular, prevención y hábitos saludables",
  smoking:
    "tabaco, efectos cardiovasculares del tabaquismo y beneficios de dejar de fumar",
  physical_activity:
    "actividad física, beneficios cardiovasculares, sedentarismo y prevención",
  weight_bmi:
    "peso corporal, IMC, relación con salud cardiovascular y prevención",
  alcohol:
    "consumo de alcohol, efectos sobre el corazón y vasos sanguíneos, patrones de consumo y prevención",
};

function interpretFeature(feature, value) {
  switch (feature) {
    case "gender":
      return genderMap[value] ?? textValue(value);
    case "smoke":
      return smokeMap[value] ?? textValue(value);
    case "alco":
      return alcoholMap[value] ?? textValue(value);
    case "active":
      return activityMap[value] ?? textValue(value);
    case "age_years":
      return `${textValue(value)} años`;
    case "height":
      return `${textValue(value)} cm`;
    case "weight":
      return `${textValue(value)} kg`;
    case "bmi":
      return `IMC ${textValue(value)}`;
    case "ap_hi":
      return `${textValue(value)} mmHg de presión sistólica`;
    case "ap_lo":
      return `${textValue(value)} mmHg de presión diastólica`;
    default:
      return textValue(value);
  }
}

// ==========================================
// 3. COHERENCIA BÁSICA DE LOS DATOS
// ==========================================

const height = numeric(user.height);
const weight = numeric(user.weight);
const bmi = numeric(user.bmi);
const systolic = numeric(user.ap_hi);
const diastolic = numeric(user.ap_lo);

const bmiCalculable =
  height !== null && height > 0 && weight !== null && weight > 0;

const calculatedBmi = bmiCalculable ? weight / Math.pow(height / 100, 2) : null;

const bmiConsistent =
  calculatedBmi !== null && bmi !== null
    ? Math.abs(calculatedBmi - bmi) <= 0.1
    : null;

const bloodPressureCoherent =
  systolic !== null && diastolic !== null ? systolic > diastolic : null;

const coherenceWarnings = [];

if (bmiConsistent === false) {
  coherenceWarnings.push(
    "Los valores de peso, estatura e IMC no son coherentes.",
  );
}

if (bloodPressureCoherent === false) {
  coherenceWarnings.push(
    "La relación entre los valores de presión arterial requiere revisión.",
  );
}

if (numeric(user.alco) === 1) {
  coherenceWarnings.push(
    "Se desconoce cantidad, frecuencia y patrón del consumo de alcohol.",
  );
}

if (numeric(user.active) === 1) {
  coherenceWarnings.push(
    "El indicador de actividad física no informa intensidad, duración ni frecuencia.",
  );
}

// ==========================================
// 4. INTERPRETACIÓN SHAP
// ==========================================

const interpretedFactors = shap.top_factors.map((f, i) => {
  const feature = String(f?.feature ?? "");
  const direction = f?.direction;
  const shapValue = numeric(f?.shap_value);

  if (
    !feature ||
    !["increase", "decrease"].includes(direction) ||
    shapValue === null
  ) {
    throw new Error(`Factor SHAP inválido en la posición ${i}.`);
  }

  const group = featureToGroup[feature] ?? null;

  return {
    priority: i + 1,
    feature,
    raw_value: f.value,
    interpreted_value: interpretFeature(feature, f.value),
    shap_value: shapValue,
    direction,
    action_group: group,
    actionable: Boolean(group),
  };
});

const weightShapHighlighted = interpretedFactors.some((f) =>
  ["weight", "bmi"].includes(f.feature),
);

if (weightShapHighlighted) {
  coherenceWarnings.push(
    "La contribución SHAP de peso o IMC no demuestra exceso de peso ni justifica por sí sola adelgazar.",
  );
}

const actionableIncreaseFactors = interpretedFactors.filter(
  (f) => f.actionable && f.direction === "increase",
);

const decreaseFactors = interpretedFactors.filter(
  (f) => f.direction === "decrease",
);

const nonActionableFactors = interpretedFactors.filter((f) => !f.actionable);

// ==========================================
// 5. POLÍTICA DE ACCIONES EDUCATIVAS
// ==========================================

/**
 * Las categorías siguientes NO son indicaciones clínicas.
 *
 * change_candidate:
 *   Puede explorarse una recomendación de cambio si
 *   el perfil y la evidencia la justifican.
 *
 * maintenance_candidate:
 *   Puede reforzarse un comportamiento favorable
 *   sin asumir que se necesita aumentarlo.
 *
 * explanation_only:
 *   Explicar el factor sin convertir automáticamente
 *   la contribución SHAP en una intervención.
 */

function classifyRecommendation(factor) {
  const { feature, direction, raw_value, action_group: group } = factor;

  if (!group) {
    return {
      category: "explanation_only",
      reason: "Factor sin acción modificable directa definida.",
    };
  }

  if (group === "weight_bmi") {
    return {
      category: "explanation_only",
      reason:
        "Peso o IMC requieren interpretación antropométrica y evidencia adicional; SHAP por sí solo no autoriza recomendar pérdida de peso.",
    };
  }

  if (feature === "alco") {
    if (numeric(raw_value) === 1) {
      return {
        category: "change_candidate",
        reason:
          "Consumo declarado; puede explicarse su relación cardiovascular y considerarse prevención sin suponer cantidades.",
      };
    }

    if (numeric(raw_value) === 0) {
      return {
        category: "maintenance_candidate",
        reason:
          "No declara consumo; se puede reforzar el mantenimiento del hábito sin afirmar consumo cero verificado.",
      };
    }
  }

  if (feature === "smoke") {
    if (numeric(raw_value) === 1) {
      return {
        category: "change_candidate",
        reason:
          "Tabaquismo declarado; requiere evidencia sobre efectos cardiovasculares y abandono.",
      };
    }

    if (numeric(raw_value) === 0) {
      return {
        category: "maintenance_candidate",
        reason:
          "No declara tabaquismo; puede reforzarse el mantenimiento del hábito.",
      };
    }
  }

  if (feature === "active") {
    if (numeric(raw_value) === 1) {
      return {
        category: "maintenance_candidate",
        reason:
          "Declara actividad física; se puede recomendar mantenerla, pero no inferir que su duración sea insuficiente.",
      };
    }

    if (numeric(raw_value) === 0) {
      return {
        category: "change_candidate",
        reason:
          "No declara actividad física; puede considerarse orientación preventiva general si existe evidencia.",
      };
    }
  }

  if (group === "blood_pressure") {
    // Este bloque solo se ejecuta si ap_hi
    // o ap_lo está presente entre los factores SHAP.

    if (
      systolic === null ||
      diastolic === null ||
      !bloodPressureCoherent ||
      systolic <= 0 ||
      diastolic <= 0
    ) {
      return {
        category: "explanation_only",
        reason:
          "Lecturas incompletas o incoherentes. " +
          "No se autoriza una orientación individual " +
          "basada en categorías de presión arterial.",
      };
    }

    if (systolic < 120 && diastolic < 80) {
      return {
        category: "explanation_only",
        reason:
          "Ambas lecturas corresponden a la categoría " +
          "educativa de presión arterial normal. " +
          "Se permite explicación sin intervención " +
          "automática.",
      };
    }

    if (systolic >= 120 && systolic < 130 && diastolic < 80) {
      return {
        category: "change_candidate",
        reason:
          "Las lecturas corresponden a presión arterial " +
          "elevada. Se permite exclusivamente orientación " +
          "educativa sobre medición, seguimiento y " +
          "prevención general, sin diagnosticar ni " +
          "establecer tratamientos.",
      };
    }

    if (systolic >= 130 || diastolic >= 80) {
      return {
        category: "change_candidate",
        reason:
          "Las cifras están en un rango educativo de " +
          "presión arterial alta. Se permite orientación " +
          "sobre medición correcta, seguimiento y " +
          "consulta con profesionales de salud. " +
          "Una lectura aislada no confirma hipertensión. " +
          "No se autorizan diagnósticos, medicamentos " +
          "ni metas terapéuticas.",
      };
    }

    return {
      category: "explanation_only",
      reason:
        "No fue posible establecer una categoría " +
        "educativa válida para las lecturas registradas.",
    };
  }

  return {
    category: "explanation_only",
    reason:
      "No existe una regla determinista suficiente para proponer una acción.",
  };
}

const classifiedFactors = interpretedFactors.map((f) => {
  const policy = classifyRecommendation(f);

  return {
    ...f,
    recommendation_category: policy.category,
    category_reason: policy.reason,
  };
});

const changeCandidates = classifiedFactors.filter(
  (f) => f.recommendation_category === "change_candidate",
);

const maintenanceCandidates = classifiedFactors.filter(
  (f) => f.recommendation_category === "maintenance_candidate",
);

const explanationOnlyFactors = classifiedFactors.filter(
  (f) => f.recommendation_category === "explanation_only",
);

const explanationFactors = classifiedFactors.map((f) => ({
  feature: f.feature,
  direction: f.direction,
  priority: f.priority,
  action_group: f.action_group,
  recommendation_category: f.recommendation_category,
}));

// Campos antiguos conservados para compatibilidad.
// Ahora hay categorías adicionales explícitas.
const allowedRecommendationFactors = [
  ...new Set(changeCandidates.map((f) => f.feature)),
];

const allowedRecommendationGroups = [
  ...new Set(changeCandidates.map((f) => f.action_group)),
];

const allowedMaintenanceFactors = [
  ...new Set(maintenanceCandidates.map((f) => f.feature)),
];

const allowedMaintenanceGroups = [
  ...new Set(maintenanceCandidates.map((f) => f.action_group)),
];

// ==========================================
// 6. CONSULTAS DOCUMENTALES
// ==========================================

const explanationGroups = [
  ...new Set(classifiedFactors.map((f) => f.action_group).filter(Boolean)),
];

const retrievalQueries = explanationGroups.map(
  (group) =>
    "Explicación científica y educación preventiva sobre " +
    groupTerms[group] +
    ".",
);

const retrievalQuery = retrievalQueries.join("\n");

// ==========================================
// 7. CONTEXTO PARA GEMINI
// NO INCLUIR DATOS DEL UMBRAL
// ==========================================

const shapText = classifiedFactors
  .map(
    (f) =>
      `${f.priority}. ${f.feature}: ${f.interpreted_value}. ` +
      `SHAP ${f.shap_value} (log-odds), dirección ${f.direction}. ` +
      `Categoría educativa: ${f.recommendation_category}.`,
  )
  .join("\n");

const changeNames =
  changeCandidates.map((f) => f.feature).join(", ") || "ninguno";

const maintenanceNames =
  maintenanceCandidates.map((f) => f.feature).join(", ") || "ninguno";

const explanationNames =
  explanationOnlyFactors.map((f) => f.feature).join(", ") || "ninguno";

const chatInput = `
Analiza los resultados de PULSO con fines exclusivamente
educativos y de prevención cardiovascular.

RESULTADO DEL MODELO
- Probabilidad estimada: ${(probability * 100).toFixed(1)}%.
- Clasificación producida por el modelo:
  ${textValue(prediction.classification)}.
- Versión del modelo:
  ${textValue(prediction.model_version)}.

PERFIL DEL USUARIO
- Sexo: ${genderMap[user.gender] ?? "desconocido"}.
- Edad: ${textValue(user.age_years)} años.
- Estatura: ${textValue(user.height)} cm.
- Peso: ${textValue(user.weight)} kg.
- IMC: ${textValue(user.bmi)}.
- Presión sistólica: ${textValue(user.ap_hi)} mmHg.
- Presión diastólica: ${textValue(user.ap_lo)} mmHg.
- Tabaquismo: ${smokeMap[user.smoke] ?? "desconocido"}.
- Alcohol: ${alcoholMap[user.alco] ?? "desconocido"}.
- Actividad física:
  ${activityMap[user.active] ?? "desconocido"}.

FACTORES SHAP
${shapText || "No disponibles."}

COHERENCIA INTERPRETATIVA
${
  coherenceWarnings.join("\n") ||
  "No se identificaron advertencias básicas de coherencia."
}

POLÍTICA EDUCATIVA
- Candidatos a recomendaciones de cambio: ${changeNames}.
- Candidatos a recomendaciones de mantenimiento:
  ${maintenanceNames}.
- Factores para explicación sin intervención automática:
  ${explanationNames}.

Una categoría es una autorización condicionada,
no una recomendación obligatoria.


OBJETIVO
1. Utilizar los factores SHAP exclusivamente
   para seleccionar las temáticas educativas.
2. Explicar la relación cardiovascular general
   de los factores autorizados mediante
   los documentos recuperados, sin interpretar
   SHAP ni los valores personales.
3. Generar, cuando corresponda, orientaciones
   preventivas adaptadas a los datos registrados
   y respaldadas documentalmente.


RESTRICCIONES
- SHAP explica el comportamiento del modelo,
  no demuestra causalidad.
- Los valores SHAP están en log-odds,
  no en puntos porcentuales.
- No utilizar el signo SHAP como diagnóstico.
- No recomendar adelgazar solo por SHAP de peso o IMC.
- No inferir cantidades ni patrones de consumo de alcohol.
- No inferir duración o intensidad de actividad física.
- Una recomendación de mantenimiento no debe convertirse
  automáticamente en una recomendación de aumentar
  la actividad o modificar el hábito.
- Los factores explanation_only pueden explicarse
  pero no originan automáticamente una intervención.

- Si ap_hi o ap_lo aparece entre los factores SHAP,
  utiliza ambas lecturas para contextualizar la
  presión arterial.
- Una lectura aislada no permite diagnosticar
  hipertensión.
- Las recomendaciones sobre presión arterial
  se limitan a educación, medición correcta,
  seguimiento y consulta profesional.
- No prescribir medicamentos ni establecer
  tratamientos o metas terapéuticas.
- La categoría change_candidate representa
  una autorización condicionada, no una
  obligación de recomendar cambios.

- No es obligatorio recomendar sobre todos los factores.
- Máximo tres recomendaciones y solo con evidencia.
- No inventar datos clínicos ni fuentes.
`.trim();

// ==========================================
// 8. SALIDA DEL NODO
// ==========================================

return {
  json: {
    chatInput,

    prediction_context: {
      probability,
      threshold,
      classification: prediction.classification,
      threshold_proximity: thresholdProximity,
      threshold_position: thresholdPosition,
      distance_to_threshold_pp: thresholdMetadata.distance_to_threshold_pp,
    },

    threshold_metadata: thresholdMetadata,

    interpreted_user_data: {
      gender: genderMap[user.gender] ?? "desconocido",
      age_years: user.age_years,
      bmi: user.bmi,
      systolic_pressure: user.ap_hi,
      diastolic_pressure: user.ap_lo,
      smoking: smokeMap[user.smoke] ?? "desconocido",
      alcohol: alcoholMap[user.alco] ?? "desconocido",
      physical_activity: activityMap[user.active] ?? "desconocido",
    },

    interpreted_shap: {
      top_factors: classifiedFactors,
    },

    recommendation_policy: {
      allowedRecommendationFactors,
      allowedRecommendationGroups,
      allowedMaintenanceFactors,
      allowedMaintenanceGroups,

      change_candidates: changeCandidates,
      maintenance_candidates: maintenanceCandidates,
      explanation_only_factors: explanationOnlyFactors,

      actionableIncreaseFactors,
      decreaseFactors,
      nonActionableFactors,
      hasActionableIncrease: actionableIncreaseFactors.length > 0,

      policy_version: "v2_change_maintenance_explanation",
    },

    explanation_policy: {
      explanationFactors,
      explanationGroups,
      shap_unit: "log_odds",
    },

    data_coherence: {
      anthropometric: {
        calculated_bmi:
          calculatedBmi === null ? null : Number(calculatedBmi.toFixed(2)),
        bmi_consistent: bmiConsistent,
        weight_shap_highlighted: weightShapHighlighted,
      },
      blood_pressure: {
        systolic_greater_than_diastolic: bloodPressureCoherent,
      },
      warnings: coherenceWarnings,
    },

    interpretation_constraints: {
      warnings: coherenceWarnings,
      no_shap_causality: true,
      no_shap_as_diagnosis: true,
      no_weight_loss_from_shap_alone: true,
      no_unknown_alcohol_consumption_assumptions: true,
      maintenance_does_not_imply_increase: true,
      threshold_interpretation_forbidden: true,
    },

    retrieval_query: retrievalQuery,
    retrieval_queries: retrievalQueries,
  },
};

/**
 * PULSO RAG v3
 * Nodo: Preparar contexto y fuentes
 * Modo: Run Once for All Items
 *
 * Salida: un item por grupo SHAP.
 * Evidencia: 5 si hay un propósito;
 * hasta 3+3 flexible si hay dos.
 *
 * Ranking híbrido inicial, ajustable tras pruebas.
 */

const original = $("Code in JavaScript").first().json;
const queries = $("Preparar consultas por factor")
  .all()
  .map((item) => item.json);

const inputItems = $input.all();

const normalize = (value) =>
  String(value ?? "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();

const rules = {
  blood_pressure: [
    "presion arterial",
    "sistolica",
    "diastolica",
    "hipertension",
    "medicion",
    "tension arterial",
  ],
  physical_activity: [
    "actividad fisica",
    "ejercicio",
    "caminar",
    "muevete",
    "sedentarismo",
  ],
  smoking: ["tabaco", "tabaquismo", "fumar", "cigarrillo"],
  alcohol: ["alcohol", "bebidas alcoholicas"],
  weight_bmi: ["peso", "imc", "indice de masa corporal", "estatura", "altura"],
  age: ["edad", "envejecimiento", "personas mayores"],
  sex: ["sexo", "genero", "mujeres", "hombres"],
};

const purposeTerms = {
  explanation: [
    "que es",
    "relacion",
    "riesgo",
    "categoria",
    "efecto",
    "beneficio",
    "comprension",
  ],
  prevention: [
    "recomendacion",
    "control",
    "mantener",
    "medicion",
    "seguimiento",
    "prevencion",
    "habito",
    "consulta",
    "dejar",
  ],
};

function parseTopics(metadata) {
  let topics = metadata.topics ?? [];

  if (typeof topics === "string") {
    try {
      topics = JSON.parse(topics);
    } catch {
      topics = [];
    }
  }

  return Array.isArray(topics) ? topics : [];
}

function candidateKey(metadata, content) {
  if (
    metadata.document_id &&
    metadata.chunk_index !== undefined &&
    metadata.chunk_index !== null
  ) {
    return metadata.document_id + "::" + metadata.chunk_index;
  }

  return String(metadata.document_id ?? "unknown") + "::" + normalize(content);
}

function isAdultMismatch(metadata, content) {
  const age = Number(original.interpreted_user_data?.age_years);

  if (!Number.isFinite(age) || age < 18) {
    return false;
  }

  const section = normalize(metadata.section_path);
  const text = normalize(content);

  return (
    /ninos|adolescentes|pediatr/.test(section) ||
    /^(#{1,4}\s*)?ninos y adolescentes\b/.test(text)
  );
}

function evaluate(candidate, group, purpose) {
  const metadata = candidate.metadata;

  const primary = metadata.topic === group;
  const secondary = parseTopics(metadata).includes(group);

  const section = normalize(metadata.section_path);
  const content = normalize(candidate.content);

  const terms = rules[group] ?? [];

  const sectionRelevant = terms.some((term) => section.includes(term));

  const contentRelevant = terms.some((term) => content.includes(term));

  // Evitar recuperar temas ajenos solo porque
  // tienen un score semántico aceptable.
  if (!primary && !(secondary && sectionRelevant && contentRelevant)) {
    return null;
  }

  if (isAdultMismatch(metadata, candidate.content)) {
    return null;
  }

  const purposeMatches = (purposeTerms[purpose] ?? []).filter(
    (term) => section.includes(term) || content.includes(term),
  ).length;

  const similarity = Number.isFinite(candidate.score) ? candidate.score : 0;

  // Ranking inicial:
  // similitud + coincidencia temática +
  // pertinencia de sección + propósito.
  // Estos pesos son heurísticos, no calibrados.
  const rankingScore =
    similarity * 0.6 +
    (primary ? 0.25 : 0.08) +
    (sectionRelevant ? 0.08 : 0) +
    (purposeMatches > 0 ? 0.07 : 0);

  return rankingScore;
}

const groupsMap = new Map();

for (const query of queries) {
  if (!groupsMap.has(query.query_group)) {
    groupsMap.set(query.query_group, {
      group: query.query_group,
      priority: query.query_priority,
      queries: [],
      candidates: new Map(),
      rejected: [],
    });
  }

  groupsMap.get(query.query_group).queries.push(query);
}

const queryMap = new Map(queries.map((q) => [q.query_id, q]));

// Vincular cada resultado a su consulta.
for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i].json ?? {};
  const origin = item.retrieval_origin ?? {};
  const query = queryMap.get(origin.query_id);

  if (
    !query ||
    query.query_group !== origin.query_group ||
    query.retrieval_purpose !== origin.retrieval_purpose
  ) {
    throw new Error(`Origen documental inválido en fragmento ${i}`);
  }

  const group = groupsMap.get(query.query_group);
  const document = item.document ?? {};
  const content = String(document.pageContent ?? "").trim();

  if (!content) {
    group.rejected.push({
      index: i,
      reason: "empty_content",
    });
    continue;
  }

  const metadata = document.metadata ?? {};
  const score = Number(item.score);

  const candidate = {
    key: candidateKey(metadata, content),
    content,
    metadata,
    score: Number.isFinite(score) ? score : null,
  };

  const rankingScore = evaluate(
    candidate,
    group.group,
    query.retrieval_purpose,
  );

  if (rankingScore === null) {
    group.rejected.push({
      index: i,
      document_id: metadata.document_id ?? null,
      chunk_index: metadata.chunk_index ?? null,
      reason: "not_relevant_or_applicable",
    });
    continue;
  }

  if (!group.candidates.has(candidate.key)) {
    group.candidates.set(candidate.key, {
      ...candidate,
      matched_queries: new Set(),
      matched_purposes: new Set(),
      purpose_scores: {},
    });
  }

  const stored = group.candidates.get(candidate.key);

  stored.matched_queries.add(query.query_id);
  stored.matched_purposes.add(query.retrieval_purpose);

  const purpose = query.retrieval_purpose;

  stored.purpose_scores[purpose] = Math.max(
    stored.purpose_scores[purpose] ?? -Infinity,
    rankingScore,
  );

  if ((candidate.score ?? -1) > (stored.score ?? -1)) {
    stored.score = candidate.score;
  }
}

function rankForPurpose(candidates, purpose) {
  return candidates
    .filter((c) => c.matched_purposes.has(purpose))
    .sort(
      (a, b) =>
        (b.purpose_scores[purpose] ?? 0) - (a.purpose_scores[purpose] ?? 0),
    );
}

const outputs = [];

const orderedGroups = [...groupsMap.values()].sort(
  (a, b) => a.priority - b.priority,
);

for (const group of orderedGroups) {
  const candidates = [...group.candidates.values()];

  const purposes = [...new Set(group.queries.map((q) => q.retrieval_purpose))];

  const explanation = rankForPurpose(candidates, "explanation");
  const prevention = rankForPurpose(candidates, "prevention");

  const maxChunks = purposes.length === 1 ? 5 : 6;

  const selected = [];
  const selectedKeys = new Set();

  function addFrom(pool, limit) {
    let added = 0;

    for (const candidate of pool) {
      if (selected.length >= maxChunks) break;
      if (added >= limit) break;
      if (selectedKeys.has(candidate.key)) continue;

      selected.push(candidate);
      selectedKeys.add(candidate.key);
      added++;
    }
  }

  if (purposes.length === 1) {
    const pool = purposes[0] === "explanation" ? explanation : prevention;

    addFrom(pool, 5);
  } else {
    // Distribución inicial 3+3.
    addFrom(explanation, 3);
    addFrom(prevention, 3);

    // Redistribución flexible, sin duplicados.
    const remaining = candidates
      .filter((c) => !selectedKeys.has(c.key))
      .sort((a, b) => {
        const bestA = Math.max(...Object.values(a.purpose_scores));
        const bestB = Math.max(...Object.values(b.purpose_scores));

        return bestB - bestA;
      });

    addFrom(remaining, maxChunks - selected.length);
  }

  const sourceMap = {};
  const retrievedChunks = [];
  const contextParts = [];

  selected.forEach((candidate, index) => {
    const sourceId = `SOURCE_${index + 1}`;
    const m = candidate.metadata;

    const sourceData = {
      source: m.source ?? "Fuente no identificada",
      score: candidate.score,
      lines: m.loc?.lines ?? null,
      document_id: m.document_id ?? null,
      chunk_index: m.chunk_index ?? null,
      section_path: m.section_path ?? null,
      source_file: m.source_file ?? null,
      source_url: m.source_url ?? null,
      pdf_url: m.pdf_url || null,
      author: m.author ?? null,
      publication_year: m.publication_year ?? null,
      language: m.language ?? null,
      topic: m.topic ?? null,
      matched_queries: [...candidate.matched_queries],
      matched_purposes: [...candidate.matched_purposes],
    };

    sourceMap[sourceId] = sourceData;

    retrievedChunks.push({
      source_id: sourceId,
      text: candidate.content,
      ...sourceData,
    });

    contextParts.push(`[${sourceId}]\n` + candidate.content);
  });

  const relatedFeatures = [
    ...new Set(group.queries.flatMap((q) => q.related_features ?? [])),
  ];

  // ==========================================
  // CONTEXTO EXCLUSIVO DE LA TEMÁTICA SHAP
  // ==========================================

  const thematicFactors = (original.interpreted_shap?.top_factors ?? []).filter(
    (f) => relatedFeatures.includes(f.feature),
  );

  const profileMatch = original.chatInput.match(
    /PERFIL DEL USUARIO\s*\n([\s\S]*?)\n\s*FACTORES SHAP/,
  );

  if (!profileMatch) {
    throw new Error("No se pudo recuperar el perfil del usuario.");
  }

  const thematicShapText = thematicFactors
    .map(
      (f) =>
        `${f.priority}. ${f.feature}: ${f.interpreted_value}. ` +
        `SHAP ${f.shap_value} (log-odds), ` +
        `dirección ${f.direction}. ` +
        `Categoría educativa: ${f.recommendation_category}. ` +
        `Restricción: ${f.category_reason}`,
    )
    .join("\n");

  const thematicChatInput = [
    "PULSO: ANÁLISIS EDUCATIVO POR TEMÁTICA",
    "",
    `TEMÁTICA AUTORIZADA: ${group.group}`,
    `VARIABLES SHAP AUTORIZADAS: ${relatedFeatures.join(", ")}`,
    "",
    "RESULTADO ORIGINAL DEL MODELO",
    `Probabilidad estimada: ${(
      original.prediction_context.probability * 100
    ).toFixed(1)}%.`,
    "No recalcular ni modificar la predicción.",
    "No interpretar umbrales de clasificación.",
    "",
    "PERFIL DEL USUARIO (SOLO CONTEXTO)",
    profileMatch[1].trim(),
    "",
    "FACTORES SHAP DE ESTA TEMÁTICA",
    thematicShapText,
    "",
    "REGLAS DE ALCANCE",

"- Ofrece educación cardiovascular general únicamente sobre la temática seleccionada mediante SHAP.",
"- No interpretes contribuciones SHAP ni valores individuales en summary.",
"- Utiliza los datos personales solo para recomendaciones autorizadas.",

    "- No generes recomendaciones sobre otras temáticas.",
    "- El resto del perfil solo sirve para verificar coherencia.",
    "- SHAP expresa contribuciones matemáticas en log-odds.",
    "- SHAP no demuestra causalidad ni diagnóstico médico.",
    "- Las categorías educativas son autorizaciones condicionadas.",
    "- No es obligatorio generar una recomendación.",
    "- Usa exclusivamente la evidencia recuperada del grupo.",
    "- Cita solo los SOURCE_X disponibles en este contexto.",
    "",
    "RESTRICCIONES ESPECÍFICAS",
    group.group === "blood_pressure"
      ? [
          "- Considera conjuntamente la lectura sistólica y diastólica.",
          "- Una lectura aislada no confirma hipertensión.",
          "- Limita la orientación a medición, seguimiento y consulta profesional.",
          "- No prescribas medicamentos ni metas terapéuticas.",
        ].join("\n")
      : "",
    group.group === "physical_activity"
      ? [
          "- No infieras duración, frecuencia ni intensidad.",
          "- Si declara actividad física, prioriza mantenimiento.",
          "- No presupongas que necesita aumentar el ejercicio.",
        ].join("\n")
      : "",
    "",
    "ADVERTENCIAS DE COHERENCIA",
    (original.interpretation_constraints?.warnings ?? []).join("\n") ||
      "Ninguna advertencia registrada.",
  ]
    .join("\n")
    .trim();

  // ==========================================
  // POLÍTICA EDUCATIVA POR TEMÁTICA
  // ==========================================

  const globalPolicy =
    original.recommendation_policy ?? {};

  const filterFactors = factors =>
    (factors ?? []).filter(
      f => relatedFeatures.includes(f.feature)
    );

  const thematicPolicy = {
    allowedRecommendationFactors:
      (globalPolicy.allowedRecommendationFactors ?? [])
        .filter(f => relatedFeatures.includes(f)),

    allowedRecommendationGroups:
      (globalPolicy.allowedRecommendationGroups ?? [])
        .filter(g => g === group.group),

    allowedMaintenanceFactors:
      (globalPolicy.allowedMaintenanceFactors ?? [])
        .filter(f => relatedFeatures.includes(f)),

    allowedMaintenanceGroups:
      (globalPolicy.allowedMaintenanceGroups ?? [])
        .filter(g => g === group.group),

    change_candidates:
      filterFactors(globalPolicy.change_candidates),

    maintenance_candidates:
      filterFactors(globalPolicy.maintenance_candidates),

    explanation_only_factors:
      filterFactors(globalPolicy.explanation_only_factors),

    policy_version: "v3_thematic"
  };

  outputs.push({
    json: {
      query_group: group.group,
      query_priority: group.priority,
      related_features: relatedFeatures,
      retrieval_purposes: purposes,

      // Se conservan para integración posterior.
      chatInput: thematicChatInput,
      prediction_context: original.prediction_context,
      interpreted_user_data: original.interpreted_user_data,
      interpreted_shap: {
        top_factors: (original.interpreted_shap?.top_factors ?? []).filter(
          (f) => relatedFeatures.includes(f.feature),
        ),
      },
      recommendation_policy:
  thematicPolicy,
      interpretation_constraints: original.interpretation_constraints,

      context: contextParts.join("\n\n---\n\n"),
      sourceMap,
      retrieved_chunks: retrievedChunks,

      retrieval_info: {
        retrieval_version: "v3_hybrid_by_theme",
        query_group: group.group,
        query_ids: group.queries.map((q) => q.query_id),
        total_candidates: inputItems.filter(
          (item) => item.json.retrieval_origin?.query_group === group.group,
        ).length,
        unique_valid_candidates: candidates.length,
        documents_retrieved: selected.length,
        source_ids: Object.keys(sourceMap),
        rejected_candidates: group.rejected,
        selected: retrievedChunks.map((c) => ({
          source_id: c.source_id,
          document_id: c.document_id,
          chunk_index: c.chunk_index,
          matched_purposes: c.matched_purposes,
          score: c.score,
        })),
      },
    },
  });
}

return outputs;

/**
 * PULSO RAG v2 — Validador final
 *
 * Nodo: Code in JavaScript1
 * Modo: Run Once for All Items
 *
 * Política:
 * - ACEPTAR o RECHAZAR recomendaciones.
 * - NUNCA reparar ni reescribir recomendaciones.
 * - Conservar el contrato RagResponse.
 * - Agregar auditoría solo al workflow de pruebas.
 *
 * Nota:
 * Las comprobaciones textuales son deterministas,
 * pero no sustituyen la validación semántica médica.
 */

// ==============================================
// 1. ENTRADAS
// ==============================================

const llmItem = $input.first().json;

const prepared =
  $("Preparar contexto y fuentes").first().json;

const original =
  $("Code in JavaScript").first().json;

const sourceMap = prepared.sourceMap ?? {};

const policy =
  original.recommendation_policy ??
  prepared.recommendation_policy ??
  {};

const retrievedChunks =
  prepared.retrieved_chunks ?? [];

const retrievalInfo =
  prepared.retrieval_info ?? {};

const NOTE =
  "PULSO ofrece información educativa y preventiva " +
  "y no constituye un diagnóstico médico.";

const NO_RECOMMENDATIONS_NOTE =
  "PULSO no pudo ofrecer recomendaciones " +
  "que cumplieran todos los criterios de validación. " +
  "La información disponible sigue siendo educativa.";

const audit = {
  policy_version:
    policy.policy_version ?? "unknown",

  accepted_recommendations: [],
  rejected_recommendations: [],
  removed_source_ids: [],
  text_warnings: [],

  total_generated: 0,
  total_accepted: 0,
  total_rejected: 0,

  evidence_absent: false,
  no_valid_recommendations: false,

  semantic_support_verified: false
};

// ==============================================
// 2. FUNCIONES AUXILIARES
// ==============================================

function asText(value) {
  return typeof value === "string"
    ? value.trim()
    : "";
}

function normalize(value) {
  return asText(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function unique(values) {
  return [...new Set(values)];
}

function reject(index, factor, reason) {
  audit.rejected_recommendations.push({
    index,
    factor,
    reason
  });
}

function accept(index, factor, feature, category, ids) {
  audit.accepted_recommendations.push({
    index,
    factor,
    feature,
    category,
    source_ids: ids
  });
}

// ==============================================
// 3. RESTRICCIONES SOBRE EL UMBRAL
// ==============================================

function containsThresholdComment(value) {
  const text = normalize(value);

  return /\b(umbral|threshold|punto de corte|puntos de corte|limite de clasificacion|distancia al limite|cercania al limite|proximidad al limite)\b/
    .test(text);
}

function fallbackSummary() {
  return (
    "PULSO ha generado una estimación mediante " +
    "un modelo de clasificación. Las características " +
    "identificadas con SHAP contribuyeron a la salida " +
    "matemática del modelo. Estas contribuciones " +
    "no constituyen un diagnóstico médico."
  );
}

function validatePublicText(value, field) {
  const text = asText(value);

  if (!text) return "";

  if (containsThresholdComment(text)) {
    audit.text_warnings.push({
      field,
      reason: "threshold_comment_detected"
    });

    return "";
  }

  return text;
}

// ==============================================
// 4. PARSEAR RESPUESTA DEL LLM
// ==============================================

const rawText = llmItem.text;

if (
  typeof rawText !== "string" ||
  !rawText.trim()
) {
  throw new Error(
    "Basic LLM Chain no devolvió un campo text válido."
  );
}

let parsed;

try {
  parsed = JSON.parse(rawText);
} catch (error) {
  throw new Error(
    "Gemini no devolvió un JSON válido."
  );
}

if (
  !parsed ||
  typeof parsed !== "object" ||
  Array.isArray(parsed)
) {
  throw new Error(
    "La respuesta debe ser un objeto JSON."
  );
}

if (!Array.isArray(parsed.recommendations)) {
  throw new Error(
    "La respuesta no contiene recommendations válido."
  );
}

audit.total_generated = parsed.recommendations.length;

// ==============================================
// 5. FACTORES Y CATEGORÍAS AUTORIZADAS
// ==============================================

const factors = [
  ...(policy.change_candidates ?? []),
  ...(policy.maintenance_candidates ?? []),
  ...(policy.explanation_only_factors ?? [])
];

if (factors.length === 0) {
  throw new Error(
    "No se encontraron factores en recommendation_policy."
  );
}

const aliases = {
  alco: [
    "alco",
    "alcohol",
    "consumo de alcohol",
    "bebidas alcoholicas"
  ],

  active: [
    "active",
    "actividad fisica",
    "ejercicio",
    "ejercicio fisico"
  ],

  smoke: [
    "smoke",
    "tabaco",
    "tabaquismo",
    "fumar",
    "consumo de tabaco"
  ],

  ap_hi: [
    "ap_hi",
    "presion sistolica",
    "presion arterial sistolica"
  ],

  ap_lo: [
    "ap_lo",
    "presion diastolica",
    "presion arterial diastolica"
  ],

  bmi: [
    "bmi",
    "imc",
    "indice de masa corporal"
  ],

  weight: [
    "weight",
    "peso",
    "peso corporal"
  ],

  age_years: [
    "age_years",
    "edad"
  ],

  gender: [
    "gender",
    "sexo",
    "genero"
  ],

  height: [
    "height",
    "estatura",
    "altura"
  ]
};

function resolveFactor(label) {
  const normalizedLabel = normalize(label);

  if (!normalizedLabel) return null;

  const matches = factors.filter(f => {
    const options =
      aliases[f.feature] ?? [f.feature];

    return options.some(
      name => normalize(name) === normalizedLabel
    );
  });

  return matches.length === 1
    ? matches[0]
    : null;
}

// ==============================================
// 6. VALIDACIONES DETERMINISTAS
// ==============================================

/**
 * No rechazamos cifras generales de alcohol
 * ni objetivos generales de actividad física.
 *
 * Solo rechazamos determinadas contradicciones
 * o afirmaciones individualizadas explícitas.
 */

function assumesExcessiveAlcoholConsumption(text) {
  const normalized = normalize(text);

  return /\b(tu consumo excesivo|su consumo excesivo|bebes demasiado|consume demasiado|tu dependencia del alcohol|su dependencia del alcohol|eres alcoholico|es alcoholico)\b/
    .test(normalized);
}

function prescribesAlcoholConsumption(text) {
  const normalized = normalize(text);

  return /\b(debes beber|debe beber|se recomienda beber|mantener el consumo de|continua bebiendo|continue bebiendo)\b/
    .test(normalized);
}

function wronglyAssumesExerciseDeficit(text) {
  const normalized = normalize(text);

  return /\b(no haces suficiente ejercicio|no realiza suficiente ejercicio|tu actividad es insuficiente|su actividad es insuficiente|eres sedentario|es sedentario|debes aumentar tu actividad|debe aumentar su actividad|mantener o aumentar|mantener o incrementar|se recomienda aumentar tu actividad|se recomienda aumentar su actividad)\b/
    .test(normalized);
}

function wronglyAssumesSmoking(text, rawValue) {
  const normalized = normalize(text);

  if (Number(rawValue) !== 0) return false;

  return /\b(deja de fumar|deje de fumar|abandona el cigarrillo|abandone el cigarrillo|reduce tu consumo de tabaco|reduzca su consumo de tabaco)\b/
    .test(normalized);
}

function violatesFactorPolicy(factor, recommendationText) {
  const category = factor.recommendation_category;

  if (category === "explanation_only") {
    return "explanation_only_factor";
  }

  if (![
    "change_candidate",
    "maintenance_candidate"
  ].includes(category)) {
    return "unauthorized_category";
  }

  if (
    containsThresholdComment(recommendationText)
  ) {
    return "threshold_comment";
  }

  if (factor.feature === "alco") {
    if (
      assumesExcessiveAlcoholConsumption(
        recommendationText
      )
    ) {
      return "unsupported_alcohol_pattern";
    }

    if (
      prescribesAlcoholConsumption(
        recommendationText
      )
    ) {
      return "alcohol_consumption_prescribed";
    }
  }

  if (
    factor.feature === "active" &&
    Number(factor.raw_value) === 1 &&
    wronglyAssumesExerciseDeficit(recommendationText)
  ) {
    return "unsupported_exercise_deficit";
  }

  if (
    factor.feature === "smoke" &&
    wronglyAssumesSmoking(
      recommendationText,
      factor.raw_value
    )
  ) {
    return "smoking_profile_contradiction";
  }

  return null;
}

// ==============================================
// 7. VALIDAR RECOMENDACIONES
// ==============================================

const validated = [];
const acceptedFeatures = new Set();

for (
  let i = 0;
  i < parsed.recommendations.length;
  i++
) {
  const rec = parsed.recommendations[i];

  if (
    !rec ||
    typeof rec !== "object" ||
    Array.isArray(rec)
  ) {
    reject(i, "", "invalid_recommendation");
    continue;
  }

  const factorLabel = asText(rec.factor);
  const recommendationText =
    asText(rec.recommendation);

  if (!factorLabel || !recommendationText) {
    reject(
      i,
      factorLabel,
      "missing_factor_or_recommendation"
    );
    continue;
  }

  if (containsThresholdComment(factorLabel)) {
    reject(
      i,
      factorLabel,
      "threshold_comment"
    );
    continue;
  }

  const factor = resolveFactor(factorLabel);

  if (!factor) {
    reject(
      i,
      factorLabel,
      "unrecognized_factor"
    );
    continue;
  }

  const violation = violatesFactorPolicy(
    factor,
    recommendationText
  );

  if (violation) {
    reject(i, factorLabel, violation);
    continue;
  }

  if (acceptedFeatures.has(factor.feature)) {
    reject(
      i,
      factorLabel,
      "duplicate_factor"
    );
    continue;
  }

  // ==========================================
  // VALIDACIÓN DE FUENTES
  // ==========================================

  const submittedIds = Array.isArray(
    rec.source_ids
  )
    ? rec.source_ids
    : [];

  const validIds = unique(
    submittedIds.filter(
      id =>
        typeof id === "string" &&
        /^SOURCE_\d+$/.test(id) &&
        Object.prototype.hasOwnProperty.call(
          sourceMap,
          id
        )
    )
  );

  for (const id of submittedIds) {
    if (!validIds.includes(id)) {
      audit.removed_source_ids.push({
        index: i,
        factor: factorLabel,
        source_id: id
      });
    }
  }

  if (validIds.length === 0) {
    reject(
      i,
      factorLabel,
      "no_valid_sources"
    );
    continue;
  }

  // Mantener el esquema exacto que espera
  // el backend de PULSO.
  const sources = validIds.map(id => ({
    source_id: id,
    source:
      sourceMap[id].source ??
      "Fuente no identificada",
    score:
      sourceMap[id].score ?? null,
    lines:
      sourceMap[id].lines ?? null
  }));

  validated.push({
    factor: factorLabel,
    recommendation: recommendationText,
    source_ids: validIds,
    sources
  });

  acceptedFeatures.add(factor.feature);

  accept(
    i,
    factorLabel,
    factor.feature,
    factor.recommendation_category,
    validIds
  );

  if (validated.length === 3) {
    // Registrar recomendaciones adicionales
    // como no procesadas por el límite.
    for (
      let j = i + 1;
      j < parsed.recommendations.length;
      j++
    ) {
      reject(
        j,
        asText(parsed.recommendations[j]?.factor),
        "maximum_three_recommendations"
      );
    }

    break;
  }
}

// ==============================================
// 8. VALIDAR RESUMEN Y CONSIDERACIONES
// ==============================================

const summary =
  validatePublicText(
    parsed.summary,
    "summary"
  ) || fallbackSummary();

const considerations =
  validatePublicText(
    parsed.considerations,
    "considerations"
  );

// ==============================================
// 9. CONTROLAR CONSISTENCIA
// ==============================================

audit.total_accepted = validated.length;

audit.total_rejected =
  audit.rejected_recommendations.length;

audit.evidence_absent =
  Object.keys(sourceMap).length === 0;

audit.no_valid_recommendations =
  validated.length === 0;

if (
  parsed.insufficient_information === true &&
  validated.length > 0
) {
  audit.text_warnings.push({
    field: "insufficient_information",
    reason:
      "llm_reported_insufficiency_but_valid_recommendations_exist"
  });
}

/**
 * Compatibilidad con RagResponse:
 *
 * insufficient_information indica que no
 * quedaron recomendaciones utilizables.
 *
 * La razón exacta se conserva en auditoría,
 * porque puede ser falta de documentos
 * o rechazo por las reglas.
 */

const insufficientInformation =
  validated.length === 0;

// ==============================================
// 10. RESPUESTA FINAL
// ==============================================

return [
  {
    json: {
      summary,

      recommendations: validated,

      considerations,

      note: insufficientInformation
        ? NO_RECOMMENDATIONS_NOTE
        : NOTE,

      insufficient_information:
        insufficientInformation,

      // SOLO EN EL WORKFLOW DE PRUEBAS
      retrieval_evaluation: {
        documents_retrieved:
          retrievalInfo.documents_retrieved ??
          retrievedChunks.length,

        chunks: retrievedChunks
      },

      // SOLO EN EL WORKFLOW DE PRUEBAS
      validation_audit: audit
    }
  }
];

/**
 * PULSO RAG v3 — Preparar consultas por factor
 *
 * Nodo: Preparar consultas por factor
 * Modo: Run Once for All Items
 *
 * ETAPA DE PRUEBA DE RETRIEVAL.
 * Todavía no implementa el Loop temático definitivo.
 *
 * Genera consultas de explicación y prevención
 * exclusivamente sobre temáticas presentes en SHAP.
 */

const original = $input.first().json;

const factors = original.interpreted_shap?.top_factors;

if (!Array.isArray(factors) || factors.length === 0) {
  throw new Error(
    "No hay factores SHAP para preparar consultas."
  );
}

// ==========================================
// 1. AGRUPACIÓN TEMÁTICA
// ==========================================

const featureGroups = {
  ap_hi: "blood_pressure",
  ap_lo: "blood_pressure",
  active: "physical_activity",
  smoke: "smoking",
  alco: "alcohol",
  weight: "weight_bmi",
  bmi: "weight_bmi",
  height: "weight_bmi",
  age_years: "age",
  gender: "sex"
};

// ==========================================
// 2. PLANTILLAS DE RECUPERACIÓN
// ==========================================

const templates = {
  blood_pressure: {
    explanation:
      "Qué son la presión arterial sistólica y diastólica, " +
      "sus categorías educativas y su relación con la " +
      "salud cardiovascular. Distinguir medición aislada " +
      "de diagnóstico.",

    prevention:
      "Cómo medir correctamente y dar seguimiento a la " +
      "presión arterial; control de cifras elevadas y " +
      "consulta con profesionales de salud, sin " +
      "diagnosticar ni prescribir tratamientos."
  },

  physical_activity: {
    explanation:
      "Relación entre actividad física y salud " +
      "cardiovascular; beneficios cardiovasculares y " +
      "limitaciones de conocer solo si una persona " +
      "declara realizar actividad.",

    prevention:
      "Orientación educativa para iniciar o mantener " +
      "actividad física según el hábito declarado; " +
      "beneficios y recomendaciones generales sin " +
      "inferir duración o intensidad individual."
  },

  smoking: {
    explanation:
      "Efectos cardiovasculares del tabaquismo y " +
      "beneficios de no fumar, incluidos factores " +
      "de riesgo y prevención.",

    prevention:
      "Orientación preventiva para dejar de fumar " +
      "cuando declara tabaquismo, o mantener la " +
      "ausencia de consumo cuando no lo declara."
  },

  alcohol: {
    explanation:
      "Relación entre el consumo de alcohol y la " +
      "salud cardiovascular, con incertidumbre " +
      "sobre cantidad y frecuencia declaradas.",

    prevention:
      "Recomendaciones de prevención cardiovascular " +
      "para reducir o evitar alcohol si declara " +
      "consumo, o mantener la ausencia de consumo " +
      "si no lo declara, sin asumir cantidades."
  },

  weight_bmi: {
    explanation:
      "Significado y limitaciones del índice de " +
      "masa corporal; relación matemática entre " +
      "peso, estatura e IMC y contextualización " +
      "cardiovascular. No inferir necesidad de " +
      "adelgazar a partir de SHAP.",

    prevention: null
  },

  age: {
    explanation:
      "Edad y envejecimiento como factores no " +
      "modificables y su relación general con la " +
      "salud cardiovascular, sin atribuir " +
      "enfermedades al individuo.",

    prevention: null
  },

  sex: {
    explanation:
      "Sexo como variable del modelo y diferencias " +
      "cardiovasculares poblacionales documentadas, " +
      "sin inferir rasgos clínicos individuales " +
      "ni confundir sexo y género.",

    prevention: null
  }
};

// ==========================================
// 3. AGRUPAR LOS FACTORES SHAP
// ==========================================

const groupMap = new Map();

for (let i = 0; i < factors.length; i++) {
  const f = factors[i];

  const group = featureGroups[f.feature];

  if (!group) {
    throw new Error(
      `Variable SHAP sin grupo definido: ${f.feature}`
    );
  }

  if (!groupMap.has(group)) {
    groupMap.set(group, {
      query_group: group,
      query_priority: Number(f.priority) || (i + 1),
      related_features: [],
      recommendation_categories: []
    });
  }

  const row = groupMap.get(group);

  row.query_priority = Math.min(
    row.query_priority,
    Number(f.priority) || (i + 1)
  );

  if (!row.related_features.includes(f.feature)) {
    row.related_features.push(f.feature);
  }

  const category =
    f.recommendation_category || "explanation_only";

  if (!row.recommendation_categories.includes(category)) {
    row.recommendation_categories.push(category);
  }
}

// ==========================================
// 4. GENERAR CONSULTAS POR PROPÓSITO
// ==========================================

const result = [];

const sortedGroups = [...groupMap.values()].sort(
  (a, b) => a.query_priority - b.query_priority
);

for (const group of sortedGroups) {
  const template = templates[group.query_group];

  if (!template) {
    throw new Error(
      `Sin plantilla de consulta: ${group.query_group}`
    );
  }

  // La explicación siempre está habilitada
  // para los factores presentes en SHAP.

  const purposes = [
    {
      kind: "explanation",
      retrieval_query: template.explanation
    }
  ];

  // La prevención depende de la política
  // educativa ya calculada en el primer Code.

  let preventive = group.recommendation_categories.some(
    c =>
      c === "change_candidate" ||
      c === "maintenance_candidate"
  );

  // ========================================
  // 5. REGLA ESPECIAL DE PRESIÓN ARTERIAL
  // ========================================

  // Solo se evalúa si ap_hi o ap_lo
  // apareció en SHAP.
  //
  // La presión arterial se contextualiza
  // utilizando ambos valores registrados.
  //
  // Una lectura aislada no constituye
  // un diagnóstico de hipertensión.

  if (group.query_group === "blood_pressure") {
    const sys = Number(
      original.interpreted_user_data?.systolic_pressure
    );

    const dia = Number(
      original.interpreted_user_data?.diastolic_pressure
    );

    preventive =
      Number.isFinite(sys) &&
      Number.isFinite(dia) &&
      (sys >= 120 || dia >= 80);
  }

  if (preventive && template.prevention) {
    purposes.push({
      kind: "prevention",
      retrieval_query: template.prevention
    });
  }

  // ========================================
  // 6. CREAR LOS ITEMS DE SALIDA
  // ========================================

  for (const purpose of purposes) {
    result.push({
      json: {
        query_id: `QUERY_${result.length + 1}`,

        query_group: group.query_group,

        query_priority: group.query_priority,

        related_features: group.related_features,

        recommendation_categories:
          group.recommendation_categories,

        retrieval_purpose: purpose.kind,

        retrieval_query: purpose.retrieval_query,

        retrieval_version:
          "v3_shap_explanation_prevention"
      }
    });
  }
}

return result;

/**
 * PULSO RAG v3
 * Nodo: Vincular fuentes con consultas
 * Modo: Run Once for All Items
 *
 * Conserva documento, score y vinculación original.
 * Añade retrieval_purpose para el ranking híbrido.
 */

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  let origin;

  try {
    origin = $(
      "Preparar consultas por factor"
    ).itemMatching(i).json;
  } catch (error) {
    throw new Error(
      `No se pudo vincular el fragmento ${i}: ` +
      error.message
    );
  }

  if (
    !origin?.query_id ||
    !origin?.query_group ||
    !["explanation", "prevention"].includes(
      origin.retrieval_purpose
    )
  ) {
    throw new Error(
      `El fragmento ${i} no tiene origen válido.`
    );
  }

  results.push({
    json: {
      ...item.json,

      retrieval_origin: {
        query_id: origin.query_id,
        query_group: origin.query_group,
        query_priority: origin.query_priority,

        retrieval_purpose:
          origin.retrieval_purpose,

        related_features:
          origin.related_features ?? [],

        recommendation_categories:
          origin.recommendation_categories ?? []
      }
    },

    pairedItem: {
      item: i
    }
  });
}

return results;

const items = $input.all();

return items.map((item, index) => ({
  json: {
    index,
    query_id:
      item.json.retrieval_origin?.query_id,
    query_group:
      item.json.retrieval_origin?.query_group,
    document_id:
      item.json.document?.metadata?.document_id,
    title:
      item.json.document?.metadata?.source,
    topic:
      item.json.document?.metadata?.topic,
    score:
      item.json.score,
    text:
      item.json.document?.pageContent
  }
}));

/**
 * PULSO RAG v3.1
 * Nodo: Validar respuesta temática
 * Modo: Run Once for All Items
 *
 * Valida la estructura, la temática,
 * la autorización y las referencias.
 *
 * No reescribe respuestas ni fabrica fuentes.
 * La verificación semántica viene después.
 */

const outputs = $input.all();

const originals = $("Preparar contexto y fuentes").all();

const expectedFields = [
  "query_group",
  "summary",
  "summary_source_ids",
  "recommendations",
  "considerations",
  "insufficient_information",
];

const allowedFactorNames = {
  blood_pressure: "presión arterial",
  physical_activity: "actividad física",
  smoking: "tabaquismo",
  alcohol: "alcohol",
  weight_bmi: "peso e IMC",
  age: "edad",
  sex: "sexo",
};

if (outputs.length !== originals.length) {
  throw new Error(
    `Cantidad de respuestas incorrecta: ` +
      `${outputs.length} frente a ${originals.length} temas.`,
  );
}

const validated = [];

for (let i = 0; i < outputs.length; i++) {
  const sourceForRejection = originals[i].json;
  try {
  const raw = outputs[i].json.text;
  const source = originals[i].json;

  if (typeof raw !== "string") {
    throw new Error(`La respuesta ${i} no contiene texto JSON.`);
  }

  let parsed;

  try {
    // Aceptar JSON puro o un único bloque Markdown externo.
    // No reparar ni extraer objetos desde texto arbitrario.
    let cleanRaw = raw.replace(/^\uFEFF/, "").trim();
    const fenced = cleanRaw.match(
      /^```(?:json)?[ \t]*\r?\n([\s\S]*?)\r?\n?```[ \t]*$/i,
    );
    if (fenced) cleanRaw = fenced[1].trim();
    parsed = JSON.parse(cleanRaw);
  } catch (error) {
    throw new Error(
      `JSON inválido en la respuesta ${i} ` +
        `(${source.query_group}): ${error.message}`,
    );
  }

  if (!parsed || Array.isArray(parsed) || typeof parsed !== "object") {
    throw new Error(`Respuesta ${i}: debe ser un objeto JSON.`);
  }

  const receivedFields = Object.keys(parsed);

  if (
    receivedFields.length !== expectedFields.length ||
    expectedFields.some((field) => !receivedFields.includes(field))
  ) {
    throw new Error(`Respuesta ${i}: estructura de campos incorrecta.`);
  }

  if (parsed.query_group !== source.query_group) {
    throw new Error(`Respuesta ${i}: temática incorrecta.`);
  }

  if (
    typeof parsed.summary !== "string" ||
    !parsed.summary.trim() ||
    typeof parsed.considerations !== "string" ||
    typeof parsed.insufficient_information !== "boolean"
  ) {
    throw new Error(`Respuesta ${i}: tipos de datos incorrectos.`);
  }

  if (
    !Array.isArray(parsed.recommendations) ||
    parsed.recommendations.length > 1
  ) {
    throw new Error(`Respuesta ${i}: máximo una recomendación.`);
  }

  const policy = source.recommendation_policy ?? {};

  const authorized =
    (policy.change_candidates?.length ?? 0) > 0 ||
    (policy.maintenance_candidates?.length ?? 0) > 0;

  if (!authorized && parsed.recommendations.length) {
    throw new Error(`Respuesta ${i}: recomendación no autorizada.`);
  }

  if (parsed.insufficient_information && parsed.recommendations.length) {
    throw new Error(`Respuesta ${i}: inconsistencia de evidencia.`);
  }

  const sourceMap = source.sourceMap ?? {};

  const summarySourceIds = parsed.summary_source_ids;

  if (
    !Array.isArray(summarySourceIds) ||
    summarySourceIds.some(
      (id) =>
        typeof id !== "string" ||
        !id.trim() ||
        !Object.prototype.hasOwnProperty.call(sourceMap, id),
    ) ||
    new Set(summarySourceIds).size !== summarySourceIds.length
  ) {
    throw new Error(`Respuesta ${i}: summary_source_ids inválidos.`);
  }

  const expectedFactor = allowedFactorNames[source.query_group];

  for (const recommendation of parsed.recommendations) {
    if (
      !recommendation ||
      typeof recommendation !== "object" ||
      Array.isArray(recommendation)
    ) {
      throw new Error(`Respuesta ${i}: recomendación inválida.`);
    }

    const keys = Object.keys(recommendation);

    if (
      keys.length !== 3 ||
      !["factor", "recommendation", "source_ids"].every((key) =>
        keys.includes(key),
      )
    ) {
      throw new Error(`Respuesta ${i}: campos de recomendación inválidos.`);
    }

    if (
      recommendation.factor !== expectedFactor ||
      typeof recommendation.recommendation !== "string" ||
      !recommendation.recommendation.trim()
    ) {
      throw new Error(`Respuesta ${i}: factor o contenido inválido.`);
    }

    if (
      !Array.isArray(recommendation.source_ids) ||
      recommendation.source_ids.length === 0 ||
      recommendation.source_ids.some(
        (id) =>
          typeof id !== "string" ||
          !Object.prototype.hasOwnProperty.call(sourceMap, id),
      )
    ) {
      throw new Error(`Respuesta ${i}: referencias inválidas.`);
    }
  }

  validated.push({
    json: {
      query_group: source.query_group,
      query_priority: source.query_priority,
      related_features: source.related_features,

      thematic_response: parsed,
      sourceMap: sourceMap,
      retrieved_chunks: source.retrieved_chunks,

      recommendation_policy: source.recommendation_policy,

      validation: {
        status: "structurally_valid",
        structural_version: "v3_4_1",
        checked_recommendations: parsed.recommendations.length,
        semantic_validation_pending: true,
      },
    },
  });

  } catch (error) {
    // No se repara ni se publica el texto generado; se preserva la posición temática.
    validated.push({ json: {
      query_group: sourceForRejection.query_group,
      query_priority: sourceForRejection.query_priority,
      related_features: sourceForRejection.related_features,
      thematic_response: {
        query_group: sourceForRejection.query_group,
        summary: "No fue posible validar el contenido educativo de esta temática.",
        summary_source_ids: [],
        recommendations: [],
        considerations: "",
        insufficient_information: true
      },
      sourceMap: sourceForRejection.sourceMap ?? {},
      retrieved_chunks: sourceForRejection.retrieved_chunks ?? [],
      recommendation_policy: sourceForRejection.recommendation_policy,
      validation: {
        status: "structurally_rejected",
        structural_version: "v3_5_low_robusto",
        checked_recommendations: 0,
        semantic_validation_pending: false,
        structural_error: String(error?.message ?? error),
        raw_response: typeof outputs[i]?.json?.text === "string" ? outputs[i].json.text : null
      }
    }});
  }
}

return validated;

/**
 * PULSO RAG v3.4 UX
 * Nodo: Consolidar respuestas temáticas
 * Modo: Run Once for All Items
 *
 * - Consolida exclusivamente temáticas aprobadas.
 * - Conserva los textos sin reescribirlos.
 * - Separa explicaciones y recomendaciones.
 * - Incorpora bibliografía propia por explicación.
 * - Conserva bibliografía propia por recomendación.
 * - Remapea identificadores locales a globales.
 * - Deduplica fuentes por documento y chunk.
 * - Aplica máximo 3 recomendaciones globales.
 * - Conserva la información de auditoría.
 */

const items = $input.all().map(item => item.json);

const MAX_RECOMMENDATIONS = 3;

const NOTE =
  "PULSO ofrece información educativa y preventiva " +
  "y no constituye un diagnóstico médico.";

function assert(condition, message) {
  if (!condition) {
    throw new Error(message);
  }
}

assert(
  items.length > 0,
  "No hay respuestas temáticas para consolidar."
);

// ================================================
// 1. ORDEN Y VALIDACIÓN DE TEMÁTICAS
// ================================================

const ordered = [...items].sort(
  (a, b) =>
    (a.query_priority ?? 999) -
    (b.query_priority ?? 999)
);

const seenGroups = new Set();

for (const item of ordered) {
  assert(
    typeof item.query_group === "string" &&
    item.query_group.trim(),
    "Elemento sin query_group válido."
  );

  assert(
    !seenGroups.has(item.query_group),
    `Temática duplicada: ${item.query_group}`
  );

  seenGroups.add(item.query_group);

  assert(
    ["approved", "rejected"].includes(
      item.semantic_validation?.status
    ),
    `Temática ${item.query_group} sin dictamen válido.`
  );

  assert(
    item.semantic_validation.approved ===
      (item.semantic_validation.status === "approved"),
    `Inconsistencia en ${item.query_group}.`
  );

  assert(
    item.thematic_response?.query_group ===
      item.query_group,
    `Respuesta temática incoherente: ${item.query_group}`
  );
}

const approved = ordered.filter(
  item =>
    item.semantic_validation.status === "approved" &&
    item.semantic_validation.approved === true
);

const rejected = ordered.filter(
  item =>
    item.semantic_validation.status !== "approved"
);

// ================================================
// 2. MAPA GLOBAL DE FUENTES
// ================================================

const globalSourceMap = {};
const sourceIdentityMap = new Map();

let sourceCounter = 0;

function getGlobalSourceId(localId, item) {
  const metadata = item.sourceMap?.[localId];

  assert(
    metadata && typeof metadata === "object",
    `Fuente inexistente: ${item.query_group}/${localId}`
  );

  const documentId = metadata.document_id;
  const chunkIndex = metadata.chunk_index;

  assert(
    typeof documentId === "string" &&
    documentId.trim() &&
    chunkIndex !== undefined &&
    chunkIndex !== null,
    `Fuente sin identidad documental: ${localId}`
  );

  const identity = `${documentId}::${chunkIndex}`;

  if (sourceIdentityMap.has(identity)) {
    return sourceIdentityMap.get(identity);
  }

  sourceCounter++;

  const globalId = `SOURCE_${sourceCounter}`;

  sourceIdentityMap.set(identity, globalId);

  globalSourceMap[globalId] = {
    ...metadata,
    source_id: globalId,
    document_id: documentId,
    chunk_index: chunkIndex
  };

  return globalId;
}

// Construir los metadatos públicos de una fuente
// a partir de su identificador global.

function buildPublicSource(globalId) {
  const metadata = globalSourceMap[globalId];

  assert(
    metadata &&
    metadata.source_id === globalId,
    `Fuente global inexistente: ${globalId}`
  );

  return {
    source_id: globalId,
    source: metadata.source,
    author: metadata.author ?? null,
    publication_year:
      metadata.publication_year ?? null,
    source_url: metadata.source_url ?? null,
    pdf_url: metadata.pdf_url ?? null,
    score: metadata.score ?? null,
    lines: metadata.lines ?? null,
    document_id: metadata.document_id,
    chunk_index: metadata.chunk_index
  };
}

// ================================================
// 3. CONTENEDORES DE SALIDA
// ================================================

const summaries = [];
const considerations = [];
const recommendations = [];
const explanationCandidates = [];
const factorExplanations = [];
const selectedGroups = [];

const factorNames = {
  blood_pressure: "presión arterial",
  physical_activity: "actividad física",
  smoking: "tabaquismo",
  alcohol: "alcohol",
  weight_bmi: "peso e IMC",
  age: "edad",
  sex: "sexo"
};

// ================================================
// 4. PROCESAR TEMÁTICAS APROBADAS
// ================================================

for (const item of approved) {
  const response = item.thematic_response;

  assert(
    typeof response.summary === "string" &&
    Array.isArray(response.summary_source_ids) &&
    Array.isArray(response.recommendations),
    `Contenido incorrecto: ${item.query_group}`
  );

  assert(
    response.recommendations.length <= 1,
    `Más de una recomendación en ${item.query_group}`
  );

  assert(
    response.summary_source_ids.every(
      id => typeof id === "string" && id.trim()
    ),
    `summary_source_ids inválidos: ${item.query_group}`
  );

  assert(
    new Set(response.summary_source_ids).size ===
    response.summary_source_ids.length,
    `Fuentes explicativas duplicadas: ${item.query_group}`
  );

  selectedGroups.push(item.query_group);

  // --------------------------------------------
  // 4A. EXPLICACIÓN TEMÁTICA
  // --------------------------------------------

  if (response.summary.trim()) {
    summaries.push(response.summary.trim());

    const policy = item.recommendation_policy ?? {};

    const features = [
      ...new Set(
        [
          ...(policy.change_candidates ?? []),
          ...(policy.maintenance_candidates ?? []),
          ...(policy.explanation_only_factors ?? [])
        ]
          .map(factor => factor.feature)
          .filter(
            feature =>
              typeof feature === "string" &&
              feature.trim()
          )
      )
    ];

    explanationCandidates.push({
      item,
      query_group: item.query_group,
      factor:
        factorNames[item.query_group] ??
        item.query_group,
      features,
      explanation: response.summary.trim(),
      localSourceIds: response.summary_source_ids
    });
  } else {
    assert(
      response.summary_source_ids.length === 0,
      `Explicación vacía con fuentes: ${item.query_group}`
    );
  }

  // --------------------------------------------
  // 4B. CONSIDERACIONES
  // --------------------------------------------

  if (
    typeof response.considerations === "string" &&
    response.considerations.trim()
  ) {
    considerations.push(
      response.considerations.trim()
    );
  }

  // --------------------------------------------
  // 4C. RECOMENDACIONES
  // --------------------------------------------

  for (const rec of response.recommendations) {
    if (
      recommendations.length >= MAX_RECOMMENDATIONS
    ) {
      break;
    }

    assert(
      typeof rec.factor === "string" &&
      rec.factor.trim() &&
      typeof rec.recommendation === "string" &&
      rec.recommendation.trim() &&
      Array.isArray(rec.source_ids) &&
      rec.source_ids.length > 0,
      `Recomendación inválida: ${item.query_group}`
    );

    assert(
      rec.source_ids.every(
        id => typeof id === "string" && id.trim()
      ),
      `Identificadores inválidos: ${item.query_group}`
    );

    const globalIds = [
      ...new Set(
        rec.source_ids.map(
          localId =>
            getGlobalSourceId(localId, item)
        )
      )
    ];

    const sources = globalIds.map(
      id => buildPublicSource(id)
    );

    recommendations.push({
      factor: rec.factor,
      recommendation: rec.recommendation,
      source_ids: globalIds,
      sources
    });
  }
}

// ================================================
// 5. BIBLIOGRAFÍA DE LAS EXPLICACIONES
// ================================================

// Se procesan después de las recomendaciones
// para conservar la numeración global previa
// de sus fuentes en el mayor grado posible.

for (const entry of explanationCandidates) {
  const globalIds = [
    ...new Set(
      entry.localSourceIds.map(
        localId =>
          getGlobalSourceId(localId, entry.item)
      )
    )
  ];

  const sources = globalIds.map(
    id => buildPublicSource(id)
  );

  factorExplanations.push({
    query_group: entry.query_group,
    factor: entry.factor,
    features: entry.features,
    explanation: entry.explanation,
    source_ids: globalIds,
    sources
  });
}

// ================================================
// 6. INFORMACIÓN INSUFICIENTE
// ================================================

const allApprovedInsufficient =
  approved.length > 0 &&
  approved.every(
    item =>
      item.thematic_response
        .insufficient_information === true
  );

const insufficientInformation =
  approved.length === 0 ||
  (
    recommendations.length === 0 &&
    allApprovedInsufficient
  );

// ================================================
// 7. BORRADOR CONSOLIDADO
// ================================================

const consolidatedDraft = {
  summary:
    summaries.join("\n\n") ||
    "No fue posible obtener explicaciones " +
    "temáticas aprobadas con la información disponible.",

  factor_explanations: factorExplanations,

  recommendations,

  considerations: considerations.join("\n\n"),

  note: NOTE,

  insufficient_information: insufficientInformation
};

// ================================================
// 8. INFORMACIÓN DE CONSOLIDACIÓN
// ================================================

return [
  {
    json: {
      consolidated_draft: consolidatedDraft,

      global_source_map: globalSourceMap,

      consolidation: {
        version: "v3_4_ux_sources",

        status:
          approved.length === 0
            ? "no_approved_themes"
            : rejected.length > 0
              ? "partial"
              : "complete",

        total_themes: ordered.length,
        approved_themes: approved.length,
        rejected_themes: rejected.length,

        included_groups: selectedGroups,

        excluded_groups: rejected.map(
          item => item.query_group
        ),

        recommendations_count:
          recommendations.length,

        explanations_count:
          factorExplanations.length,

        unique_sources_count:
          Object.keys(globalSourceMap).length,

        max_recommendations: MAX_RECOMMENDATIONS,

        final_backend_validation_pending: true
      }
    }
  }
];

/**
 * PULSO RAG v3.4 UX con fuentes explicativas
 * Nodo: Preparar respuesta final RagResponse
 * Modo: Run Once for All Items
 *
 * Conserva el contrato anterior y agrega bibliografía por explicación.
 * Conserva auditoría y recuperación solo
 * en el workflow de desarrollo.
 *
 * No modifica recomendaciones.
 */

const input = $input.all();

if (input.length !== 1) {
  throw new Error("Se esperaba un único resultado consolidado.");
}

const data = input[0].json;
const draft = data.consolidated_draft;
const consolidation = data.consolidation;
const globalSourceMap = data.global_source_map;

const includedGroups = consolidation?.included_groups ?? [];

if (!draft || !consolidation || !globalSourceMap) {
  throw new Error("Faltan datos de consolidación.");
}

const NOTE =
  "PULSO ofrece información educativa y preventiva " +
  "y no constituye un diagnóstico médico.";

const NO_RECOMMENDATIONS_NOTE =
  "PULSO no pudo ofrecer recomendaciones " +
  "que cumplieran todos los criterios de validación. " +
  "La información disponible sigue siendo educativa.";

function assert(condition, message) {
  if (!condition) {
    throw new Error(message);
  }
}

function asText(value) {
  return typeof value === "string" ? value.trim() : "";
}

function normalize(value) {
  return asText(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function containsThresholdComment(value) {
  return /\b(umbral|threshold|punto de corte|puntos de corte|limite de clasificacion|distancia al limite|cercania al limite|proximidad al limite)\b/.test(
    normalize(value),
  );
}

const audit = {
  policy_version: "v3_thematic",

  accepted_recommendations: [],
  rejected_recommendations: [],
  removed_source_ids: [],
  text_warnings: [],

  total_generated: 0,
  total_accepted: 0,
  total_rejected: 0,

  evidence_absent: false,
  no_valid_recommendations: false,

  semantic_support_verified: false,

  semantic_auditor_approved: false,

  consolidation_version: consolidation.version,

  consolidation_status: consolidation.status,

  approved_themes: consolidation.approved_themes,

  rejected_themes: consolidation.rejected_themes,

  thematic_audits: [],
};

// Recuperar los dictámenes de cada temática.
const thematicItems = $("Validación determinista sin auditor")
  .all()
  .map((item) => item.json);

const thematicGroups = new Set();

for (const item of thematicItems) {
  assert(
    !thematicGroups.has(item.query_group),
    `Temática duplicada: ${item.query_group}`,
  );

  thematicGroups.add(item.query_group);

  audit.thematic_audits.push({
    query_group: item.query_group,
    decision: "not_performed",
    validation_status: item.semantic_validation?.approved === true ? "structurally_valid" : "structurally_rejected",
    approved: false, // Sin dictamen semántico independiente.
    critical_errors: item.audit_result?.critical_errors ?? [],
    warnings: item.audit_result?.warnings ?? [],
    rejected_reasons: item.semantic_validation?.rejected_reasons ?? [],
    structural_error: item.semantic_validation?.structural_error ?? null,
  });

  const generated = item.thematic_response?.recommendations ?? [];

  audit.total_generated += generated.length;

  if (item.semantic_validation?.approved !== true) {
    generated.forEach((rec, index) => {
      audit.rejected_recommendations.push({
        index,
        query_group: item.query_group,
        factor: rec.factor ?? "",
        reason: "structural_validation_rejected",
      });
    });
  }
}

assert(
  thematicItems.length === consolidation.total_themes,
  "No coincide la cantidad de temáticas.",
);

assert(
  Array.isArray(draft.recommendations),
  "recommendations debe ser un arreglo.",
);

assert(
  draft.recommendations.length <= 3,
  "Se excedió el límite de recomendaciones.",
);

// Validar y adaptar fuentes.
const validated = [];

for (const rec of draft.recommendations) {
  assert(
    asText(rec.factor) && asText(rec.recommendation),
    "Recomendación sin contenido válido.",
  );

  assert(
    !containsThresholdComment(rec.factor) &&
      !containsThresholdComment(rec.recommendation),
    "La recomendación menciona el umbral.",
  );

  assert(
    Array.isArray(rec.source_ids) && rec.source_ids.length > 0,
    "Recomendación sin fuentes.",
  );

  const ids = [...new Set(rec.source_ids)];

  assert(
    ids.length === rec.source_ids.length,
    "Identificadores de fuente duplicados.",
  );

  const sources = ids.map((id) => {
    const metadata = globalSourceMap[id];

    assert(
      metadata && typeof metadata === "object",
      `Fuente inexistente: ${id}`,
    );

    assert(metadata.source_id === id, `Identidad de fuente incorrecta: ${id}`);

    assert(asText(metadata.source), `Título de fuente ausente: ${id}`);

    return {
      source_id: id,

      source: metadata.source,

      author: metadata.author ?? null,

      publication_year: metadata.publication_year ?? null,

      source_url: metadata.source_url ?? null,

      pdf_url: metadata.pdf_url ?? null,

      score: metadata.score ?? null,

      lines: metadata.lines ?? null,
    };
  });

  validated.push({
    factor: rec.factor,
    recommendation: rec.recommendation,
    source_ids: ids,
    sources,
  });

  audit.accepted_recommendations.push({
    index: validated.length - 1,
    factor: rec.factor,
    source_ids: ids,
  });
}

// Verificar que el consolidador no haya
// omitido recomendaciones aprobadas sin
// contabilizarlas mediante el límite global.
const approvedGenerated = thematicItems
  .filter((item) => item.semantic_validation?.approved === true)
  .reduce(
    (sum, item) => sum + (item.thematic_response?.recommendations?.length ?? 0),
    0,
  );

assert(
  validated.length === Math.min(approvedGenerated, 3),
  "Inconsistencia en la cantidad consolidada.",
);

// Registrar recomendaciones aprobadas,
// pero excluidas por el máximo de tres.
let capacity = 3;

const prioritized = thematicItems
  .filter((item) => item.semantic_validation?.approved === true)
  .sort((a, b) => (a.query_priority ?? 999) - (b.query_priority ?? 999));

for (const item of prioritized) {
  for (const rec of item.thematic_response?.recommendations ?? []) {
    if (capacity > 0) {
      capacity--;
    } else {
      audit.rejected_recommendations.push({
        query_group: item.query_group,
        factor: rec.factor,
        reason: "maximum_three_recommendations",
      });
    }
  }
}

audit.total_accepted = validated.length;
audit.total_rejected = audit.rejected_recommendations.length;

audit.no_valid_recommendations = validated.length === 0;

audit.evidence_absent = Object.keys(globalSourceMap).length === 0;

// Registra aprobación del auditor,
// sin afirmar verificación médica absoluta.
audit.semantic_auditor_approved = false;
audit.semantic_auditor_performed = false;
audit.validation_mode = "deterministic_only_no_semantic_auditor";

// Recuperar evidencia temática para
// el diagnóstico de retrieval en desarrollo.
const contextItems = $("Preparar contexto y fuentes")
  .all()
  .map((item) => item.json);

const uniqueChunks = new Map();

// Relacionar cada documento y chunk con el
// identificador global de la consolidación.
const globalIdsByDocumentChunk = new Map();

for (const [globalId, metadata] of Object.entries(globalSourceMap)) {
  const key = JSON.stringify([metadata.document_id, metadata.chunk_index]);

  if (globalIdsByDocumentChunk.has(key)) {
    throw new Error(`Identidad documental duplicada: ${key}`);
  }

  globalIdsByDocumentChunk.set(key, globalId);
}

// Reconstruir los fragmentos de auditoría
// utilizando identificadores globales.
for (const context of contextItems) {
  for (const chunk of context.retrieved_chunks ?? []) {
    const key = JSON.stringify([chunk.document_id, chunk.chunk_index]);

    if (uniqueChunks.has(key)) {
      continue;
    }

    const globalId = globalIdsByDocumentChunk.get(key);

    uniqueChunks.set(key, {
      ...chunk,

      // Solo los fragmentos citados poseen
      // identificador global.
      source_id: globalId ?? null,

      // Preservar el identificador original
      // para la auditoría técnica.
      local_source_id: chunk.source_id,

      // Identificar la temática original.
      query_group: context.query_group,
    });
  }
}

/**
 * PULSO RAG v3.4
 * Evidencia de recuperación bruta para evaluación.
 *
 * Conserva los resultados de Supabase ANTES del
 * filtrado temático y del ranking híbrido.
 *
 * No modifica la recuperación ni la respuesta.
 */

const retrievalResults = $("Vincular fuentes con consultas").all();

const preparedQueries = $("Preparar consultas por factor")
  .all()
  .map((item) => item.json);

// Inicializar todas las consultas, incluso si
// alguna no tiene resultados.
const rawQueriesMap = new Map();

for (const query of preparedQueries) {
  assert(
    query.query_id && !rawQueriesMap.has(query.query_id),
    `Consulta duplicada o inválida: ${query.query_id}`,
  );

  rawQueriesMap.set(query.query_id, {
    query_id: query.query_id,
    query_group: query.query_group,
    retrieval_purpose: query.retrieval_purpose,
    retrieval_query: query.retrieval_query,
    top_k_requested: 5,
    results_count: 0,
    results: [],
  });
}

// Extraer los resultados sin aplicar nuevos
// filtros ni alterar su contenido original.
for (const item of retrievalResults) {
  const data = item.json ?? {};
  const origin = data.retrieval_origin ?? {};
  const document = data.document ?? {};
  const metadata = document.metadata ?? {};

  const query = rawQueriesMap.get(origin.query_id);

  assert(query, `Resultado sin consulta válida: ${origin.query_id}`);

  assert(
    query.query_group === origin.query_group &&
      query.retrieval_purpose === origin.retrieval_purpose,
    `Origen inconsistente: ${origin.query_id}`,
  );

  const score = Number(data.score);

  query.results.push({
    rank: null,

    document_id: metadata.document_id ?? null,

    chunk_index: metadata.chunk_index ?? null,

    score: Number.isFinite(score) ? score : null,

    topic: metadata.topic ?? null,

    topics: metadata.topics ?? null,

    source: metadata.source ?? null,

    section_path: metadata.section_path ?? null,

    source_file: metadata.source_file ?? null,

    text: document.pageContent ?? "",

    author: metadata.author ?? null,

    publication_year: metadata.publication_year ?? null,

    source_url: metadata.source_url ?? null,

    pdf_url: metadata.pdf_url ?? null,
  });
}

// Conservar los resultados sin deduplicarlos.
// Ordenar por score para definir el rango
// usado en Precision@5 y Hit Rate@5.
for (const query of rawQueriesMap.values()) {
  query.results.sort((a, b) => {
    if (a.score === null && b.score === null) {
      return 0;
    }

    if (a.score === null) return 1;
    if (b.score === null) return -1;

    return b.score - a.score;
  });

  query.results.forEach((result, index) => {
    result.rank = index + 1;
  });

  query.results_count = query.results.length;
}

const rawQueries = [...rawQueriesMap.values()];

// Mantener el contrato anterior y añadir
// la evidencia de recuperación original.
const retrievalEvaluation = {
  documents_retrieved: retrievalResults.length,

  chunks: [...uniqueChunks.values()],

  raw_queries: rawQueries,
};

// Conservar el control de texto público de v2.
const fallbackSummary =
  "No fue posible obtener explicaciones temáticas aprobadas " +
  "con la información disponible.";

function validatePublicText(value, field) {
  const text = asText(value);

  if (!text) return "";

  if (containsThresholdComment(text)) {
    audit.text_warnings.push({
      field,
      reason: "threshold_comment_detected",
    });

    return "";
  }

  return text;
}

const summary = validatePublicText(draft.summary, "summary") || fallbackSummary;

const considerations = validatePublicText(
  draft.considerations,
  "considerations",
);

// Contrato UX aditivo.
// Solo pueden incluirse temáticas aprobadas.

assert(
  Array.isArray(draft.factor_explanations),
  "factor_explanations debe ser un arreglo."
);

function getPublicSource(id) {
  const metadata = globalSourceMap[id];

  assert(
    metadata && typeof metadata === "object",
    `Fuente inexistente: ${id}`
  );

  assert(
    metadata.source_id === id,
    `Identidad de fuente incorrecta: ${id}`
  );

  assert(
    asText(metadata.source),
    `Título de fuente ausente: ${id}`
  );

  assert(
    typeof metadata.document_id === "string" &&
      metadata.document_id.trim() &&
      metadata.chunk_index !== null &&
      metadata.chunk_index !== undefined,
    `Identidad documental incompleta: ${id}`
  );

  return {
    source_id: id,
    source: metadata.source,
    author: metadata.author ?? null,
    publication_year: metadata.publication_year ?? null,
    source_url: metadata.source_url ?? null,
    pdf_url: metadata.pdf_url ?? null,
    score: metadata.score ?? null,
    lines: metadata.lines ?? null
  };
}

const factorExplanations = draft.factor_explanations.map((entry) => {
  assert(
    typeof entry.query_group === "string" &&
      includedGroups.includes(entry.query_group) &&
      asText(entry.factor) &&
      Array.isArray(entry.features) &&
      entry.features.every(
        feature => typeof feature === "string"
      ) &&
      Array.isArray(entry.source_ids) &&
      Array.isArray(entry.sources),
    `Explicación temática inválida o no aprobada: ${entry.query_group}`
  );

  const explanation = validatePublicText(
    entry.explanation,
    `factor_explanations.${entry.query_group}`
  );

  assert(
    explanation,
    `Explicación vacía o prohibida: ${entry.query_group}`
  );

  const thematic = thematicItems.find(item =>
    item.query_group === entry.query_group &&
    item.semantic_validation?.approved === true &&
    item.validation_method === "deterministic_structural_only"
  );

  assert(
    thematic,
    `No existe aprobación temática: ${entry.query_group}`
  );

  assert(
    explanation === asText(thematic.thematic_response?.summary),
    `La explicación se modificó después de validarse: ${entry.query_group}`
  );

  const localIds =
    thematic.thematic_response?.summary_source_ids;

  assert(
    Array.isArray(localIds) &&
      localIds.every(
        id => typeof id === "string" && id.trim()
      ) &&
      new Set(localIds).size === localIds.length,
    `Citas locales inválidas: ${entry.query_group}`
  );

  const ids = entry.source_ids;

  assert(
    ids.every(
      id => typeof id === "string" && id.trim()
    ) &&
      new Set(ids).size === ids.length &&
      ids.length === localIds.length,
    `Citas globales inválidas: ${entry.query_group}`
  );

  // Comparar identidades documento/chunk, no SOURCE_X local.
  // SOURCE_1 puede representar otro documento en cada temática.

  const expectedIdentity = new Map();
  const sourceMap = thematic.sourceMap ?? {};

  // No hay evaluaciones semánticas de fuentes; se valida solamente identidad documental.

  for (const localId of localIds) {
    const metadata = sourceMap[localId];

    assert(
      metadata &&
        typeof metadata.document_id === "string" &&
        metadata.chunk_index !== null &&
        metadata.chunk_index !== undefined,
      `Fuente local inexistente: ${entry.query_group}/${localId}`
    );

    // El respaldo semántico NO se verifica en esta variante.

    const key = JSON.stringify([
      metadata.document_id,
      String(metadata.chunk_index)
    ]);

    assert(
      !expectedIdentity.has(key),
      `Fragmento local duplicado: ${key}`
    );

    expectedIdentity.set(key, localId);
  }

  const sources = ids.map(id => {
    const metadata = globalSourceMap[id];

    const publicSource = getPublicSource(id);

    const key = JSON.stringify([
      metadata.document_id,
      String(metadata.chunk_index)
    ]);

    assert(
      expectedIdentity.has(key),
      `Cita global no corresponde a la explicación: ${entry.query_group}/${id}`
    );

    expectedIdentity.delete(key);

    return publicSource;
  });

  assert(
    expectedIdentity.size === 0,
    `Faltan fuentes explicativas: ${entry.query_group}`
  );

  // Verificar que el borrador no intercambió fuentes.
  assert(
    entry.sources.length === ids.length &&
      entry.sources.every(
        (source, i) => source?.source_id === ids[i]
      ),
    `Bibliografía del borrador incoherente: ${entry.query_group}`
  );

  return {
    query_group: entry.query_group,
    factor: entry.factor,
    features: entry.features,
    explanation,
    source_ids: ids,
    sources
  };
});

assert(
  factorExplanations.length ===
    new Set(
      factorExplanations.map(x => x.query_group)
    ).size,
  "Explicaciones temáticas duplicadas."
);

// Una temática aprobada con explicación válida no es
// un fallo de información por carecer de recomendación.
// El fallback se activa únicamente cuando no hay contenido
// educativo temático aprobado disponible para entregar.

const insufficientInformation =
  validated.length === 0 &&
  factorExplanations.length === 0;

// CONTRATO FINAL DEL WORKFLOW DE DESARROLLO

return [
  {
    json: {
      summary,

      recommendations: validated,

      factor_explanations: factorExplanations,

      considerations,

      note: insufficientInformation
        ? NO_RECOMMENDATIONS_NOTE
        : NOTE,

      insufficient_information: insufficientInformation,

      retrieval_evaluation: retrievalEvaluation,

      validation_audit: audit,
    },
  },
];

/**
 * PULSO RAG v3.4
 * Nodo: Preparar respuesta final RagResponse
 * Modo: Run Once for All Items
 *
 * Adapta v3 al contrato de salida de v2.
 * Conserva auditoría y recuperación solo
 * en el workflow de desarrollo.
 *
 * No modifica recomendaciones.
 */

const input = $input.all();

if (input.length !== 1) {
  throw new Error(
    "Se esperaba un único resultado consolidado."
  );
}

const data = input[0].json;
const draft = data.consolidated_draft;
const consolidation = data.consolidation;
const globalSourceMap = data.global_source_map;

if (
  !draft ||
  !consolidation ||
  !globalSourceMap
) {
  throw new Error(
    "Faltan datos de consolidación."
  );
}

const NOTE =
  "PULSO ofrece información educativa y preventiva " +
  "y no constituye un diagnóstico médico.";

const NO_RECOMMENDATIONS_NOTE =
  "PULSO no pudo ofrecer recomendaciones " +
  "que cumplieran todos los criterios de validación. " +
  "La información disponible sigue siendo educativa.";

function assert(condition, message) {
  if (!condition) {
    throw new Error(message);
  }
}

function asText(value) {
  return typeof value === "string"
    ? value.trim()
    : "";
}

function normalize(value) {
  return asText(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function containsThresholdComment(value) {
  return /\b(umbral|threshold|punto de corte|puntos de corte|limite de clasificacion|distancia al limite|cercania al limite|proximidad al limite)\b/
    .test(normalize(value));
}

const audit = {
  policy_version: "v3_thematic",

  accepted_recommendations: [],
  rejected_recommendations: [],
  removed_source_ids: [],
  text_warnings: [],

  total_generated: 0,
  total_accepted: 0,
  total_rejected: 0,

  evidence_absent: false,
  no_valid_recommendations: false,

  semantic_support_verified: false,

  semantic_auditor_approved: false,

  consolidation_version:
    consolidation.version,

  consolidation_status:
    consolidation.status,

  approved_themes:
    consolidation.approved_themes,

  rejected_themes:
    consolidation.rejected_themes,

  thematic_audits: []
};

// Recuperar los dictámenes de cada temática.
const thematicItems = $(
  "Validar auditoría semántica"
).all().map(item => item.json);

const thematicGroups = new Set();

for (const item of thematicItems) {
  assert(
    !thematicGroups.has(item.query_group),
    `Temática duplicada: ${item.query_group}`
  );

  thematicGroups.add(item.query_group);

  audit.thematic_audits.push({
    query_group: item.query_group,
    decision:
      item.audit_result?.decision ?? null,
    validation_status:
      item.semantic_validation?.status ?? null,
    approved:
      item.semantic_validation?.approved === true,
    critical_errors:
      item.audit_result?.critical_errors ?? [],
    warnings:
      item.audit_result?.warnings ?? [],
    rejected_reasons:
      item.semantic_validation
        ?.rejected_reasons ?? []
  });

  const generated =
    item.thematic_response?.recommendations ?? [];

  audit.total_generated += generated.length;

  if (
    item.semantic_validation?.approved !== true
  ) {
    generated.forEach((rec, index) => {
      audit.rejected_recommendations.push({
        index,
        query_group: item.query_group,
        factor: rec.factor ?? "",
        reason: "semantic_audit_rejected"
      });
    });
  }
}

assert(
  thematicItems.length ===
    consolidation.total_themes,
  "No coincide la cantidad de temáticas."
);

assert(
  Array.isArray(draft.recommendations),
  "recommendations debe ser un arreglo."
);

assert(
  draft.recommendations.length <= 3,
  "Se excedió el límite de recomendaciones."
);

// Validar y adaptar fuentes.
const validated = [];

for (const rec of draft.recommendations) {
  assert(
    asText(rec.factor) &&
    asText(rec.recommendation),
    "Recomendación sin contenido válido."
  );

  assert(
    !containsThresholdComment(rec.factor) &&
    !containsThresholdComment(rec.recommendation),
    "La recomendación menciona el umbral."
  );

  assert(
    Array.isArray(rec.source_ids) &&
    rec.source_ids.length > 0,
    "Recomendación sin fuentes."
  );

  const ids = [...new Set(rec.source_ids)];

  assert(
    ids.length === rec.source_ids.length,
    "Identificadores de fuente duplicados."
  );

  const sources = ids.map(id => {
    const metadata = globalSourceMap[id];

    assert(
      metadata &&
      typeof metadata === "object",
      `Fuente inexistente: ${id}`
    );

    assert(
      metadata.source_id === id,
      `Identidad de fuente incorrecta: ${id}`
    );

    assert(
      asText(metadata.source),
      `Título de fuente ausente: ${id}`
    );


return {
  source_id: id,

  source: metadata.source,

  author: metadata.author ?? null,

  publication_year:
    metadata.publication_year ?? null,

  source_url: metadata.source_url ?? null,

  pdf_url: metadata.pdf_url ?? null,

  score: metadata.score ?? null,

  lines: metadata.lines ?? null
};

  });

  validated.push({
    factor: rec.factor,
    recommendation: rec.recommendation,
    source_ids: ids,
    sources
  });

  audit.accepted_recommendations.push({
    index: validated.length - 1,
    factor: rec.factor,
    source_ids: ids
  });
}

// Verificar que el consolidador no haya
// omitido recomendaciones aprobadas sin
// contabilizarlas mediante el límite global.
const approvedGenerated = thematicItems
  .filter(
    item =>
      item.semantic_validation?.approved === true
  )
  .reduce(
    (sum, item) =>
      sum +
      (item.thematic_response
        ?.recommendations?.length ?? 0),
    0
  );

assert(
  validated.length === Math.min(
    approvedGenerated,
    3
  ),
  "Inconsistencia en la cantidad consolidada."
);

// Registrar recomendaciones aprobadas,
// pero excluidas por el máximo de tres.
let capacity = 3;

const prioritized = thematicItems
  .filter(
    item =>
      item.semantic_validation?.approved === true
  )
  .sort(
    (a, b) =>
      (a.query_priority ?? 999) -
      (b.query_priority ?? 999)
  );

for (const item of prioritized) {
  for (
    const rec of
      item.thematic_response?.recommendations ?? []
  ) {
    if (capacity > 0) {
      capacity--;
    } else {
      audit.rejected_recommendations.push({
        query_group: item.query_group,
        factor: rec.factor,
        reason: "maximum_three_recommendations"
      });
    }
  }
}

audit.total_accepted = validated.length;
audit.total_rejected =
  audit.rejected_recommendations.length;

audit.no_valid_recommendations =
  validated.length === 0;

audit.evidence_absent =
  Object.keys(globalSourceMap).length === 0;

// Registra aprobación del auditor,
// sin afirmar verificación médica absoluta.
audit.semantic_auditor_approved =
  validated.length > 0 &&
  thematicItems
    .filter(
      item =>
        item.semantic_validation?.approved === true
    )
    .every(
      item =>
        item.audit_result?.decision === "approve"
    );

// Recuperar evidencia temática para
// el diagnóstico de retrieval en desarrollo.
const contextItems = $(
  "Preparar contexto y fuentes"
).all().map(item => item.json);


const uniqueChunks = new Map();

// Relacionar cada documento y chunk con el
// identificador global de la consolidación.
const globalIdsByDocumentChunk = new Map();

for (const [globalId, metadata] of Object.entries(
  globalSourceMap
)) {
  const key = JSON.stringify([
    metadata.document_id,
    metadata.chunk_index
  ]);

  if (globalIdsByDocumentChunk.has(key)) {
    throw new Error(
      `Identidad documental duplicada: ${key}`
    );
  }

  globalIdsByDocumentChunk.set(key, globalId);
}

// Reconstruir los fragmentos de auditoría
// utilizando identificadores globales.
for (const context of contextItems) {
  for (const chunk of context.retrieved_chunks ?? []) {

    const key = JSON.stringify([
      chunk.document_id,
      chunk.chunk_index
    ]);

    if (uniqueChunks.has(key)) {
      continue;
    }

    const globalId =
      globalIdsByDocumentChunk.get(key);

    uniqueChunks.set(key, {
      ...chunk,

      // Solo los fragmentos citados poseen
      // identificador global.
      source_id: globalId ?? null,

      // Preservar el identificador original
      // para la auditoría técnica.
      local_source_id: chunk.source_id,

      // Identificar la temática original.
      query_group: context.query_group
    });
  }
}

const retrievalResults = $(
  "Vincular fuentes con consultas"
).all();

const retrievalEvaluation = {
  documents_retrieved:
    retrievalResults.length,

  chunks: [...uniqueChunks.values()]
};

// Conservar el control de texto público de v2.
const fallbackSummary =
  "PULSO ha generado una estimación mediante " +
  "un modelo de clasificación. Las características " +
  "identificadas con SHAP contribuyeron a la salida " +
  "matemática del modelo. Estas contribuciones " +
  "no constituyen un diagnóstico médico.";

function validatePublicText(value, field) {
  const text = asText(value);

  if (!text) return "";

  if (containsThresholdComment(text)) {
    audit.text_warnings.push({
      field,
      reason: "threshold_comment_detected"
    });

    return "";
  }

  return text;
}

const summary =
  validatePublicText(draft.summary, "summary") ||
  fallbackSummary;

const considerations =
  validatePublicText(
    draft.considerations,
    "considerations"
  );

// Igual que en v2: si no quedan recomendaciones
// utilizables, insufficient_information es true.
const insufficientInformation =
  validated.length === 0;

// CONTRATO FINAL DEL WORKFLOW DE DESARROLLO
return [
  {
    json: {
      summary,

      recommendations: validated,

      considerations,

      note: insufficientInformation
        ? NO_RECOMMENDATIONS_NOTE
        : NOTE,

      insufficient_information:
        insufficientInformation,

      retrieval_evaluation:
        retrievalEvaluation,

      validation_audit: audit
    }
  }
];

/**
 * PULSO RAG v3.4.1 - ablación SIN AUDITOR SEMÁNTICO.
 * Entrada: Validar respuesta temática (estructura y citas locales).
 * No realiza inferencias clínicas ni verifica respaldo semántico.
 * El campo semantic_validation se conserva SOLO para compatibilidad interna.
 * `approved` significa aquí APTO ESTRUCTURALMENTE, no auditado por IA.
 */
const inputs = $input.all();
const output = [];
const seen = new Set();
for (let i = 0; i < inputs.length; i++) {
  const data = inputs[i].json;
  const group = data.query_group;
  if (typeof group !== 'string' || !group.trim() || seen.has(group)) {
    throw new Error(`Tema inválido/duplicado: ${String(group)}`);
  }
  seen.add(group);
  const valid = data.validation?.status === 'structurally_valid';
  const rejected = data.validation?.status === 'structurally_rejected';
  if (!valid && !rejected) {
    throw new Error(`Tema ${group}: validación estructural ausente`);
  }
  const response = data.thematic_response;
  if (!response || response.query_group !== group) {
    throw new Error(`Tema ${group}: respuesta incoherente`);
  }
  const sourceMap = data.sourceMap ?? {};
  if (valid) {
    const ids = [
      ...(response.summary_source_ids ?? []),
      ...(response.recommendations ?? []).flatMap(r => r.source_ids ?? []),
    ];
    for (const id of ids) {
      const src = sourceMap[id];
      if (!src || typeof src.document_id !== 'string' || !src.document_id.trim() ||
          src.chunk_index === null || src.chunk_index === undefined) {
        throw new Error(`Tema ${group}: fuente local inválida ${String(id)}`);
      }
    }
  }
  output.push({
    json: {
      query_group: group,
      query_priority: data.query_priority,
      thematic_response: response,
      sourceMap,
      recommendation_policy: data.recommendation_policy,
      audit_result: null,
      validation_method: 'deterministic_structural_only',
      semantic_validation: {
        status: valid ? 'approved' : 'rejected',
        approved: valid,
        // Compatibilidad de consolidador; NO implica evaluación semántica.
        validation_type: 'structural_only',
        independent_semantic_audit_performed: false,
        validator_version: 'v3_4_1_no_auditor',
        cited_sources: 0,
        audited_sources: 0,
        rejected_reasons: rejected ? ['generator_structural_invalid'] : [],
        structural_error: rejected ? (data.validation?.structural_error ?? 'invalid_structure') : null,
      },
    },
    pairedItem: { item: i },
  });
}
return output;
